export default {
  version: 1,
  name: "Moon Gravity",
  description: "Gentle gravity lets the courier stay airborne longer and float farther with each jump.",
  rules: [
    {
      id: "moon-gravity",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        { type: "physics", target: "self", gravityScale: 0.3 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Second Jump",
  description: "Jump once more in midair. Landing restores your extra jump.",
  rules: [
    {
      id: "extra-airborne-jump",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        { type: "physics", target: "self", airJumps: 1 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Grow While Holding Interact",
  description: "Hold interact to grow to 1.6 times your normal size where space allows. Release it to return to normal size.",
  rules: [
    {
      id: "grow-while-held",
      each: "player",
      on: "tick",
      when: {
        compare: {
          left: { field: "inputInteract" },
          op: "eq",
          right: 1
        }
      },
      actions: [
        {
          type: "physics",
          target: "self",
          playerScale: 1.6,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Lantern Gusts",
  description: "A steady gust pushes every movable crate to the right while it is within 220 world units of a lantern.",
  rules: [
    {
      id: "lantern-gust",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "distanceToLantern" },
          op: "lte",
          right: 220
        }
      },
      actions: [
        {
          type: "physics",
          target: "self",
          windX: 0.08,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Slow Nearby Crates",
  description: "Movable crates within 200 units of you move at half speed. They return to normal speed farther away.",
  rules: [
    {
      id: "slow-nearby-crates",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "distanceToPlayer" },
          op: "lte",
          right: 200
        }
      },
      actions: [
        {
          type: "physics",
          target: "self",
          timeScale: 0.5,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Rubber Ember",
  description: "The dropped ember bounces like a rubber ball until you pick it up again.",
  rules: [
    {
      id: "dropped-ember-bounce",
      each: "ember",
      on: "tick",
      when: {
        compare: {
          left: { field: "emberCarried" },
          op: "eq",
          right: 0
        }
      },
      actions: [
        {
          type: "material",
          target: "self",
          friction: 0.95,
          bounce: 0.9,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Landing Steps",
  description: "Each landing creates a solid stepping platform beside the courier to the right. Each platform lasts three seconds, with up to eight present at once.",
  rules: [
    {
      id: "landing-step",
      each: "player",
      on: "land",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        {
          type: "spawnPlatform",
          offsetX: 64,
          offsetY: 0,
          width: 80,
          lifetime: 180,
          solid: true,
          maxCount: 8
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Running jumps",
  description: "The faster you run, the stronger your next jump becomes, up to 60% stronger than a standing jump.",
  rules: [
    {
      id: "speed-strengthens-jumps",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        {
          type: "physics",
          target: "self",
          jumpStrength: {
            clamp: {
              value: { add: [1, { mul: [{ field: "speed" }, 0.05] }] },
              min: 1,
              max: 1.6
            }
          }
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Bouncy Crates",
  description: "Touch a crate to make it bouncy for three seconds.",
  rules: [
    {
      id: "crate-touch-bounce",
      each: "prop",
      on: "touch",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        { type: "material", target: "self", friction: 0.85, bounce: 0.85, lifetime: 180 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Still Shadows",
  description: "Leave a crate still for half a second and its shadow from a nearby lit lantern becomes a solid bridge. Move the crate to remove the bridge.",
  rules: [
    {
      id: "still-prop-shadow-bridge",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "stationaryTicks" },
          op: "gte",
          right: 30
        }
      },
      actions: [
        {
          type: "projectShadow",
          maxLength: 320,
          thickness: 10,
          lifetime: 1,
          solid: true
        }
      ]
    }
  ]
} satisfies RuleModule;
